&lt;li data-local-id=&quot;dc36a721fac3&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Local development environment tooling (devcontainers, Tilt, Skaffold, or similar).&lt;/li&gt;
&lt;li data-local-id=&quot;4b6991943424&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Kubernetes or cloud-native OSS contributions.&lt;/li&gt;
&lt;/ul&gt;
